// Adapted from internal-case-management-system src/services/caseService.ts:94-120
// @ 4bbcf27 (buildCaseAccessWhere from src/lib/auth/authorize.ts:42-58 and a minimal
// where-matcher over an in-memory case list inlined; the access scope is spread AFTER the
// client's filters — finding A1's fix shape — so the module runs standalone).
export class AuthorizationError extends Error {}

const ALL_CASES_ROLES = new Set(['ADMIN', 'OPERATIONS_MANAGER', 'AUDITOR']);

export function buildCaseAccessWhere(actor) {
  if (ALL_CASES_ROLES.has(actor.role)) {
    return {};
  }
  if (!actor.teamId) {
    throw new AuthorizationError('This role requires a team assignment before it can access cases.');
  }
  // The team filter is centralized here so callers cannot silently forget it.
  return { owningTeamId: actor.teamId };
}

export function buildCaseListWhere(actor, filters) {
  const accessWhere = buildCaseAccessWhere(actor);

  return {
    ...(filters.status ? { status: filters.status } : {}),
    ...(filters.assignedToId ? { assignedToId: filters.assignedToId } : {}),
    ...(filters.owningTeamId ? { owningTeamId: filters.owningTeamId } : {}),
    // The access scope is spread LAST. Object spread is last-writer-wins, so a client
    // filter may narrow what the scope allows but can never replace it (finding A1).
    ...accessWhere,
  };
}

export function matchesWhere(record, where) {
  return Object.entries(where).every(([field, expected]) => record[field] === expected);
}

export async function listVisibleCases(store, actor, filters) {
  const where = buildCaseListWhere(actor, filters);
  const cases = await store.listCases();
  return cases.filter((record) => matchesWhere(record, where));
}

