// Adapted from internal-case-management-system src/services/caseService.ts:404-455
// @ 4bbcf27 (Prisma replaced by an in-memory store; canViewRestrictedNotes reduced to the
// note:view:restricted role set from src/lib/auth/permissions.ts; audit metadata limited
// to non-sensitive transition facts — finding A2's fix — so the module runs standalone).
const RESTRICTED_NOTE_ROLES = new Set(['ADMIN', 'OPERATIONS_MANAGER', 'TEAM_LEAD', 'AUDITOR']);

export function canViewRestrictedNotes(actor) {
  return RESTRICTED_NOTE_ROLES.has(actor.role);
}

export class InMemoryCaseStore {
  constructor(caseRecord) {
    this.caseRecord = { notes: [], auditLogs: [], ...caseRecord };
  }
  async findCaseById(caseId) {
    return this.caseRecord.id === caseId ? this.caseRecord : null;
  }
  async updateCaseRecord(caseId, data) {
    Object.assign(this.caseRecord, data);
    return this.caseRecord;
  }
  async createAuditLog(entry) {
    this.caseRecord.auditLogs.push(entry);
  }
  async createCaseNote(note) {
    this.caseRecord.notes.push(note);
  }
}

export function serializeCaseDetail(actor, caseRecord) {
  return {
    ...caseRecord,
    // Restricted notes are filtered here; every other field of the record — auditLogs
    // included — is spread through to the response as-is.
    notes: caseRecord.notes.filter((note) => !note.isRestricted || canViewRestrictedNotes(actor)),
  };
}

export async function transitionCase(store, actor, caseId, input) {
  const existingCase = await store.findCaseById(caseId);
  const previousStatus = existingCase.status;
  await store.updateCaseRecord(caseId, { status: input.nextStatus });

  // Finding A2: the comment below may become a RESTRICTED note, but auditLogs are spread
  // to every viewer of the case, so audit metadata records only non-sensitive facts.
  await store.createAuditLog({
    caseId,
    actorId: actor.id,
    action: 'case.transitioned',
    metadata: {
      from: previousStatus,
      to: input.nextStatus,
    },
  });

  if (input.comment) {
    await store.createCaseNote({
      caseId,
      authorId: actor.id,
      body: input.comment,
      isRestricted: input.nextStatus === 'ESCALATED',
    });
  }

  return serializeCaseDetail(actor, await store.findCaseById(caseId));
}

